// Read-only validation: proposed documents must fail executable grant checks.
package main
import("encoding/json";"fmt";"os";"path/filepath";"time";"github.com/tokenbeat-lab/barness/ai/internal/testkit/supportmatrix")
func main(){os.Chdir("/Users/cyber/RestoX/barness");paths,_:=filepath.Glob(".scratch/provider-final-readiness/kimi-scopes-v2/*.json");ok:=len(paths)==6;var out []map[string]any;for _,p:=range paths{raw,e:=os.ReadFile(p);if e!=nil{panic(e)};var doc struct{DocumentType,Route string;Approved,GrantIssued,Executable bool};if json.Unmarshal(raw,&doc)!=nil{panic("proposal")};var g supportmatrix.RegionalGrant;e=json.Unmarshal(raw,&g);if e==nil{e=g.Check(doc.Route,time.Now().UTC())};rejected:=e!=nil;ok=ok&&rejected&&!doc.Approved&&!doc.GrantIssued&&!doc.Executable&&doc.DocumentType=="KIMI_PAID_SCOPE_PROPOSAL_NOT_A_GRANT";out=append(out,map[string]any{"route":doc.Route,"executableGrantRejected":rejected,"approved":doc.Approved,"issued":doc.GrantIssued})};b,_:=json.MarshalIndent(out,"","  ");fmt.Println(string(b));if !ok{os.Exit(1)}}
